	[Test]
	public async Task PictureBoxClickShouldFire()
	{
		var isClickFired = false;
		using var ctx = new WinzorTestContext();
		PictureBox pictureBox = null;
		var rendered = await ctx.RenderFormAsync(() =>
		{
			var form = new Form();
			form.Size = new Size(500, 500);
			pictureBox = new PictureBox { Image = pngImage.ToImage(), BorderStyle = BorderStyle.Fixed3D, Width = 200, Height = 200 };
			form.Controls.Add(pictureBox);
			pictureBox.MouseClick += (sender, e) => { isClickFired = true; };

			return form;
		});

		Assert.That(isClickFired, Is.False);

		await rendered.Find(".picturebox").ClickAsync(new WebMouseEventArgs());

		Assert.That(isClickFired, Is.True);
	}

	[Test, WithPlaywrightPage]
	public async Task ImageShouldNotHaveScrollbarsWith3dBorder()
	{
		await using var ctx = new InMemoryTestServerContext();
		Form form = null;
		var page = await ctx.LoadFormAsync(() =>
		{
			form = new Form();
			var pictureBox = new PictureBox { Image = pngImage.ToImage(), BorderStyle = BorderStyle.Fixed3D, Width = 200, Height = 200 };
			form.Controls.Add(pictureBox);
			return form;
		});

		var pictureBox = await page.WaitForSelectorAsync(".picturebox");
		Assert.That(async () => await pictureBox.EvaluateAsync<bool>("e => e.scrollHeight == e.clientHeight && e.scrollWidth == e.clientWidth"), Is.True);
	}

