	[TestCase(BorderStyle.None, 0, 10, 10)]
	[TestCase(BorderStyle.FixedSingle, 1, 11, 11)]
	[TestCase(BorderStyle.Fixed3D, 2, 13, 13)]

	public async Task TestBorderStyleAdjustForClientSize(BorderStyle bs, int borderSize, int drawingBoundsX, int drawingBoundsY)
	{
		using var ctx = new WinzorTestContext();
		PictureBox targetPictureBox = null;
		var rendered = await ctx.RenderFormAsync(() =>
		{
			var form = new Form();
			form.Size = new Size(500, 500);
			targetPictureBox = new PictureBox { Image = pngImage.ToImage(), BorderStyle = bs, Width = 200, Height = 200 };
			form.Controls.Add(targetPictureBox);
			targetPictureBox.Location = new Point(10, 10);

			return form;
		});

		var b = targetPictureBox.Bounds;
		Assert.That(b.X, Is.EqualTo(10));
		Assert.That(b.Y, Is.EqualTo(10));
		Assert.That(targetPictureBox.ClientSize.Width + 2 * borderSize, Is.EqualTo(b.Width));
		Assert.That(targetPictureBox.ClientSize.Height + 2 * borderSize, Is.EqualTo(b.Height));
		Assert.That(targetPictureBox.ClientAreaBounds.X, Is.EqualTo(drawingBoundsX));
		Assert.That(targetPictureBox.ClientAreaBounds.Y, Is.EqualTo(drawingBoundsY));
	}

	[TestCase(BorderStyle.None, BorderStyle.FixedSingle, true, 2)]
	[TestCase(BorderStyle.None, BorderStyle.Fixed3D, true, 4)]
	[TestCase(BorderStyle.None, BorderStyle.None, false, 0)]
	public async Task BorderStyleChangeTriggersRecalculation(BorderStyle initial, BorderStyle bs, bool expectChange, int expectedDiff)
	{
		using var ctx = new WinzorTestContext();
		PictureBox targetPictureBox = null;

		bool clientSizeChanged = false;
		int clientSizeDiff = 0;

		var rendered = await ctx.RenderFormAsync(() =>
		{
			var form = new Form();
			form.Size = new Size(500, 500);
			targetPictureBox = new PictureBox { Image = pngImage.ToImage(), BorderStyle = BorderStyle.None, Width = 200, Height = 200 };
			form.Controls.Add(targetPictureBox);

			var clientSizeBefore = targetPictureBox.ClientSize;
			targetPictureBox.ClientSizeChanged += (sender, e) =>
			{
				clientSizeChanged = true;
				clientSizeDiff = clientSizeBefore.Width - targetPictureBox.ClientSize.Width;
			};

			return form;
		});

		clientSizeChanged = false;

		await targetPictureBox.InvokeWinzorDispatcherAsync(() =>
		{
			targetPictureBox.BorderStyle = bs;
		});

		Assert.That(clientSizeChanged, Is.EqualTo(expectChange));
		Assert.That(clientSizeDiff, Is.EqualTo(expectedDiff));
	}

	[Test]
	public async Task PictureBoxHidesOverlappingPixelsInTableLayout()
	{
		PictureBox leftPictureBox = null;
		PictureBox rightPictureBox = null;

		using var ctx = new WinzorTestContext();
		var rendered = await ctx.RenderFormAsync(() =>
		{
			var form = new Form();

			leftPictureBox = new PictureBox { Image = pngImage.ToImage(), Width = 200, Height = 200, MinimumSize = new Size(200, 200), SizeMode = PictureBoxSizeMode.CenterImage };
			rightPictureBox = new PictureBox { Image = pngImage.ToImage(), Width = 200, Height = 200, MinimumSize = new Size(200, 200), SizeMode = PictureBoxSizeMode.CenterImage };

			var tableLayoutPanel = new TableLayoutPanel() { ColumnCount = 3, RowCount = 1, AutoSize = false };
			tableLayoutPanel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 200));
			tableLayoutPanel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
			tableLayoutPanel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 200));
			tableLayoutPanel.RowStyles.Add(new RowStyle(SizeType.Absolute, 200));
			tableLayoutPanel.Controls.Add(leftPictureBox, 0, 0);
			tableLayoutPanel.Controls.Add(new Label() { Text = "Sample Text" }, 1, 0);
			tableLayoutPanel.Controls.Add(rightPictureBox, 2, 0);
			tableLayoutPanel.Size = new Size(300, 200);

			form.Controls.Add(tableLayoutPanel);
			return form;
		});

		var pictureBox = rendered.FindAll(".picturebox")[1];
		Assert.That(pictureBox.GetStyle().GetPropertyValue("width"), Is.EqualTo("99px"));

		Assert.That(leftPictureBox.Width, Is.EqualTo(200));
		Assert.That(rightPictureBox.Width, Is.EqualTo(200));
	}

	[Test, WithPlaywrightPage]
	public async Task PictureBoxWithCenterAlignPlacement()
	{
		await using var ctx = new InMemoryTestServerContext();
		Form form = null;
		Size boxSize = new Size(200, 200);
		var page = await ctx.LoadFormAsync(() =>
		{
			form = new Form();
			form.Size = new Size(500, 500);
			var pictureBox = new PictureBox { Image = pngImage.ToImage(), BorderStyle = BorderStyle.Fixed3D, Width = boxSize.Width, Height = boxSize.Height, SizeMode = PictureBoxSizeMode.CenterImage };
			form.Controls.Add(pictureBox);
			return form;
		});
		var pictureBox = await page.WaitForSelectorAsync(".picturebox");
		var imgageTab = await page.WaitForSelectorAsync("img");
		var box = await  pictureBox.BoundingBoxAsync();
		var imageBox = await imgageTab.BoundingBoxAsync();

		Assert.That(async () => await imgageTab.EvaluateAsync<string>("e => window.getComputedStyle(e).getPropertyValue('top')"), Is.EqualTo((boxSize.Width * 0.5) + "px"));
		Assert.That(async () => await imgageTab.EvaluateAsync<string>("e => window.getComputedStyle(e).getPropertyValue('left')"), Is.EqualTo((boxSize.Width * 0.5) + "px"));

		Assert.That((box.X - (imageBox.Width - box.Width) / 2) ,Is.EqualTo(imageBox.X));
		Assert.That((box.Y - (imageBox.Height - box.Height) / 2), Is.EqualTo(imageBox.Y));
	}

